-- Generated by build_world_batch.py. See its docstring and each
-- region's notes; style.json holds every claim's sources.

begin;

insert into public.wine_regions
  (region_code, name, aliases, country_code, latitude, longitude, radius_km,
   summary, red_body, red_acidity, red_tannin, pairing, label_note,
   source_url, publication_status)
values
  ('wr_0160', 'Abruzzo', '{"Montepulciano d''Abruzzo"}'::text[], 'IT', 42.368, 14.072, 42,
   'Hill vineyards between the Apennines and the Adriatic, where the sea moderates the climate, grow Montepulciano on clay and limestone soils. The reds have a medium to full body and lively acidity.',
   4, 4, null, 'Lamb, above all grilled lamb skewers.', 'At least 85 percent Montepulciano. Colline Teramane DOCG needs at least 90 percent, one year of ageing, and three years with one in wood for Riserva.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_E-N/Montepulciano_d''Abruzzo.pdf', 'published'),
  ('wr_0161', 'Verdicchio di Matelica', '{"Matelica"}'::text[], 'IT', 43.245, 12.967, 14,
   'A closed inland valley in the Apennines, cut off from the sea, with cool nights and limestone and clay soils. Its Verdicchio is crisper and more mineral than coastal Jesi, with firm acidity.',
   null, null, null, 'Fish and seafood.', 'At least 85 percent Verdicchio. Verdicchio di Matelica Riserva DOCG needs at least 18 months of ageing from 1 December after the harvest.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_O-Z/Verdicchio_di_Matelica.pdf', 'published'),
  ('wr_0162', 'Castelli di Jesi', '{"Verdicchio dei Castelli di Jesi","Jesi"}'::text[], 'IT', 43.521, 13.244, 30,
   'Hills along the Esino valley about 20 km from the Adriatic, on clay rich soils with limestone, give Verdicchio that is rounder and softer than Matelica''s, with citrus fruit and high acidity.',
   null, null, null, 'Fish and seafood.', 'At least 85 percent Verdicchio. Classico comes from the older core of the zone. Castelli di Jesi Verdicchio Riserva DOCG needs at least 18 months of ageing, six of them in bottle.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_O-Z/Verdicchio_dei_Castelli_di_Jesi.pdf', 'published'),
  ('wr_0163', 'Primitivo di Manduria', '{"Manduria"}'::text[], 'IT', 40.422, 17.506, 18,
   'Flat land sloping to the Ionian Sea east of Taranto, with a hot, dry, breezy Mediterranean climate and clay and limestone soils, gives full, intensely flavoured Primitivo with high alcohol and soft tannins.',
   null, null, 2, 'Grilled meats and roast lamb.', 'At least 85 percent Primitivo. Riserva needs 24 months of ageing, at least nine in wood. The sweet Dolce Naturale is a separate DOCG from 100 percent Primitivo.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_O-Z/Primitivo_di_Manduria.pdf', 'published'),
  ('wr_0164', 'Sardinia', '{"Sardegna","Cannonau di Sardegna"}'::text[], 'IT', 40.062, 9.097, 88,
   'Cannonau grows across the whole island in a hot, dry and windy Mediterranean climate, on soils ranging from granite and schist to basalt and clay. The wines are full bodied and high in alcohol, with red fruit and soft acidity.',
   5, 2, 2, 'Roast pork and other roasted meats.', 'Cannonau di Sardegna: at least 85 percent Cannonau, 90 percent for Classico from Nuoro and Ogliastra. Riserva needs two years of ageing with six months in wood. Vermentino di Sardegna: at least 85 percent Vermentino.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_A-D/Cannonau_di_Sardegna.pdf', 'published'),
  ('wr_0165', 'Gallura', '{"Vermentino di Gallura"}'::text[], 'IT', 40.964, 9.212, 31,
   'Weathered granite soils, constant wind and marked swings between day and night temperatures in Sardinia''s north east give Vermentino with intensity and bright, refreshing acidity.',
   null, null, null, 'Seafood.', 'At least 95 percent Vermentino.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_O-Z/Vermentino_di_Gallura.pdf', 'published'),
  ('wr_0166', 'Marsala', '{}'::text[], 'IT', 37.866, 12.697, 27,
   'Low vineyards, 50 to 300 metres up across the province of Trapani at Sicily''s western tip, with hot, dry summers and clay, sand and limestone soils, make fortified wines that range from dry to sweet.',
   null, null, null, 'Sweet Marsala with cannoli; drier styles with cheese.', 'Oro and ambra from Grillo, Catarratto, Inzolia or Damaschino; rubino from red grapes. Ageing sets the label: Fine one year, Superiore two, Superiore Riserva four, Vergine five, Vergine Stravecchio or Riserva ten.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_E-N/Marsala.pdf', 'published'),
  ('wr_0167', 'Cerasuolo di Vittoria', '{"Vittoria"}'::text[], 'IT', 37.067, 14.481, 29,
   'South east Sicily, near the sea, with a hot, dry climate and sandy, iron rich red soils over limestone, gives Nero d''Avola and Frappato blends known for their freshness.',
   null, null, null, null, 'Nero d''Avola 50 to 70 percent with Frappato 30 to 50 percent.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_A-D/Cerasuolo_di_Vittoria.pdf', 'published'),
  ('wr_0168', 'Trentodoc', '{"Trento DOC","Trento"}'::text[], 'IT', 45.974, 11.104, 27,
   'Mountain vineyards in the valleys of Trentino, mostly on stony, well drained limestone slopes up to about 800 metres, see wide swings between day and night temperatures. The sparkling wines are fresh and precise, with bright acidity.',
   null, null, null, null, 'Bottle fermented from Chardonnay, Pinot Bianco, Pinot Nero and Meunier. At least 15 months on the lees; 24 for a vintage on the label; 36 for Riserva.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_O-Z/Trento.pdf', 'published'),
  ('wr_0169', 'Lugana', '{}'::text[], 'IT', 45.451, 10.562, 8,
   'On the southern shore of Lake Garda, Turbiana grows on compact clay soils in a mild climate shaped by the lake. The wines are citrusy and fresh, with lively acidity and often a note of almond.',
   null, null, null, 'Freshwater fish from the lake, such as trout or pike.', 'Turbiana, with up to 10 percent other white grapes. Superiore needs 12 months of ageing; Riserva 24 months, six in bottle.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_E-N/Lugana.pdf', 'published'),
  ('wr_0170', 'Lambrusco di Sorbara', '{"Sorbara"}'::text[], 'IT', 44.686, 10.959, 15,
   'On the plain around Modena, between the Secchia and Panaro rivers, vines grow on soils laid down by the rivers. The wines are pale, light bodied sparkling reds with high acidity and very little tannin.',
   2, 5, 1, null, 'At least 60 percent Lambrusco di Sorbara, with up to 40 percent Lambrusco Salamino. Made only as frizzante and spumante.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_E-N/Lambrusco_di_Sorbara.pdf', 'published'),
  ('wr_0171', 'Lambrusco Grasparossa di Castelvetro', '{"Grasparossa","Castelvetro"}'::text[], 'IT', 44.564, 10.953, 16,
   'In the foothills and low hills south of Modena, around Castelvetro, Grasparossa gives the darkest of the Lambruscos, deep coloured sparkling reds with more body and tannin than the other styles.',
   null, null, null, null, 'At least 85 percent Lambrusco Grasparossa. Made only as frizzante and spumante.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_E-N/Lambrusco_Grasparossa_di_Castelvetro.pdf', 'published'),
  ('wr_0172', 'Valtellina', '{"Valtellina Superiore"}'::text[], 'IT', 46.183, 9.917, 30,
   'Nebbiolo, called Chiavennasca here, grows on steep, south facing terraces held up by dry stone walls on the Rhaetian Alps side of the valley, in shallow sandy soils from granite. The reds are marked by high acidity.',
   null, 4, null, 'Pizzoccheri, the buckwheat pasta of the valley.', 'At least 90 percent Nebbiolo. Valtellina Superiore needs 24 months of ageing, 12 in wood, and three years for Riserva. Sforzato is made from dried grapes.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_O-Z/Valtellina_superiore.pdf', 'published'),
  ('wr_0173', 'Montefalco', '{"Montefalco Sagrantino"}'::text[], 'IT', 42.901, 12.578, 10,
   'Around the hill town of Montefalco in central Umbria, vines grow on gentle hills of clay, sand and marl in a continental climate. Sagrantino makes powerful, full bodied reds with very high tannin.',
   5, null, 5, 'Roast wild boar.', 'Montefalco Sagrantino is 100 percent Sagrantino, aged at least 33 months plus four in bottle. Montefalco Rosso is 60 to 80 percent Sangiovese with 10 to 25 percent Sagrantino.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_E-N/Montefalco_Sagrantino.pdf', 'published'),
  ('wr_0174', 'Fiano di Avellino', '{}'::text[], 'IT', 40.912, 14.788, 9,
   'Fiano grows on the hills around Avellino, on volcanic ash over clay and limestone, in a cool climate with snowy winters and wide day to night swings. The wines keep firm acidity and gain toasted nut notes with age.',
   null, null, null, null, 'At least 85 percent Fiano. Riserva needs 12 months of ageing; spumante 18 months in bottle, 36 for Spumante Riserva.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_E-N/Fiano_di_Avellino.pdf', 'published'),
  ('wr_0175', 'Greco di Tufo', '{}'::text[], 'IT', 41.019, 14.823, 5,
   'In eight villages of the Sabato valley in Irpinia, Greco grows on volcanic, clay and limestone soils in a cool climate with wide day to night swings. The wines have high acidity, a firm grip and a pleasant bitter finish.',
   null, null, null, 'Seafood and shellfish.', 'At least 85 percent Greco, with up to 15 percent Coda di Volpe. Riserva needs 12 months; spumante 18 months on the lees, 36 for Spumante Riserva.',
   'https://www.masaf.gov.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/4625#Disciplinari_DOP_E-N/Greco_di_Tufo.pdf', 'published'),
  ('wr_0176', 'Ribeira Sacra', '{"DO Ribeira Sacra","DOP Ribeira Sacra"}'::text[], 'ES', 42.399, -7.516, 30,
   'Ribeira Sacra follows the steep banks of the Miño and Sil rivers in southern Lugo and northern Ourense. It is best known for fresh, light red wines from Mencía grown on terraced slopes.',
   2, null, null, null, null,
   'https://guiapenin.wine/en-ribeira-sacra-do-dop', 'published'),
  ('wr_0177', 'Valdeorras', '{"DO Valdeorras","DOP Valdeorras"}'::text[], 'ES', 42.367, -6.969, 15,
   'Valdeorras is Galicia''s easternmost appellation, in Ourense province bordering Bierzo. It is known above all for white wines from Godello, with a smaller share of red wines from Mencía.',
   null, null, null, null, 'Wines from raisined grapes are labelled ''tostado''. ''Producción controlada'' is reserved for reds and Godello whites from vineyards classed as such.',
   'https://vinepair.com/articles/galicia-spain-definitive-guide/', 'published'),
  ('wr_0178', 'Ribeiro', '{"DO Ribeiro","DOP Ribeiro"}'::text[], 'ES', 42.352, -8.144, 12,
   'Ribeiro lies in western Ourense along the Miño river and its tributaries. It is mainly a white wine region, known for aromatic blends led by Treixadura, often with Torrontés.',
   null, null, null, null, 'Wines based on the principal varieties may be labelled ''castes'', ''barrica'', ''espumoso'' or ''tostado''; tostado is made from raisined grapes.',
   'https://guiapenin.wine/en-ribeiro-do-dop', 'published'),
  ('wr_0179', 'Monterrei', '{"DO Monterrei","DOP Monterrei"}'::text[], 'ES', 42.013, -7.421, 18,
   'Monterrei sits in southeastern Ourense on the border with Portugal. It is mainly a white wine region led by Godello, with red wines made chiefly from Mencía.',
   null, null, null, null, null,
   'https://guiapenin.wine/en-monterrei-do-dop', 'published'),
  ('wr_0180', 'Getariako Txakolina', '{"Txakoli de Getaria","Chacolí de Getaria"}'::text[], 'ES', 43.157, -2.207, 25,
   'Txakoli from the Basque province of Gipuzkoa, with most vineyards around the coastal towns of Getaria, Zarautz and Aia. Mostly a pale, light white with high acidity and a slight spritz, made chiefly from Hondarrabi Zuri.',
   null, null, null, 'Seafood and pintxos', '''Vendimia tardía'' may be used for wines from overripe grapes of at least 12% alcohol.',
   'https://guiapenin.wine/en-getariako-txakolina-do-dop', 'published'),
  ('wr_0181', 'Bizkaiko Txakolina', '{"Txakoli de Bizkaia"}'::text[], 'ES', 43.238, -2.863, 27,
   'Txakoli from the Basque province of Bizkaia, around Bilbao, in coastal and inland valleys. Mostly a light, crisp white with high acidity, made from Hondarrabi Zuri, with Folle Blanche adding a herbal note.',
   null, null, null, 'Raw seafood such as oysters', '''Vendimia tardía'' may be used alongside the name Bizkaia for late harvest wines.',
   'https://guiapenin.wine/en-bizkaiko-txakolina-do-dop', 'published'),
  ('wr_0182', 'Navarra', '{"Navarre"}'::text[], 'ES', 42.400, -1.616, 37,
   'Wine region across the northern Spanish province of Navarra, split into five subzones. Best known for fresh, fruity Grenache rosado made by bleeding the tank, and also for reds from Grenache, Tempranillo and international grapes.',
   null, null, null, null, null,
   'https://guiapenin.wine/en-navarra-do-dop', 'published'),
  ('wr_0183', 'Cigales', '{}'::text[], 'ES', 41.798, -4.649, 13,
   'Small region north of Valladolid on both banks of the Pisuerga river, reaching into Palencia province. Best known for rosado and also making reds, with Tempranillo, locally Tinta del País, the dominant grape.',
   null, null, null, null, null,
   'https://guiapenin.wine/en-cigales-do-dop', 'published'),
  ('wr_0184', 'Somontano', '{}'::text[], 'ES', 42.097, 0.036, 26,
   'Somontano lies in Huesca province in Aragón, northeast Spain. It is known for international grapes such as Cabernet Sauvignon, Merlot, Chardonnay and Gewürztraminer, grown alongside the native red grapes Moristel and Parraleta.',
   null, null, null, null, null,
   'https://www.spain.info/en/oenology/wine-route-somontano/', 'published'),
  ('wr_0185', 'Calatayud', '{}'::text[], 'ES', 41.310, -1.714, 26,
   'Calatayud lies in the west of Zaragoza province in Aragón, with vineyards set high in the hills. It is known above all for red wines from Garnacha, much of it from old vines, along with fresh Garnacha rosés.',
   null, null, null, null, 'Optional label terms include ''Calatayud Superior'' and ''Viñas viejas'' (old vines).',
   'https://www.spain.info/en/oenology/calatayud-wine-route/', 'published'),
  ('wr_0186', 'Campo de Borja', '{}'::text[], 'ES', 41.785, -1.508, 15,
   'Campo de Borja lies in northwest Zaragoza province in Aragón, between the Moncayo foothills and the Ebro valley. Garnacha dominates its vineyards, many of them old, and it is best known for Garnacha red wines.',
   null, null, null, null, null,
   'https://guiapenin.wine/en-campo-de-borja-do-dop', 'published'),
  ('wr_0187', 'Jumilla', '{}'::text[], 'ES', 38.596, -1.564, 28,
   'Jumilla spans the provinces of Murcia and Albacete in southeastern Spain. It is known for bold, deeply coloured red wines from Monastrell, the grape that covers most of its vineyards.',
   5, null, 4, 'Grilled meats', '''Viña vieja'' is reserved for wines made from at least 85% grapes from vineyards at least 30 years old.',
   'https://guiapenin.wine/en-jumilla-do-dop', 'published'),
  ('wr_0188', 'Montsant', '{}'::text[], 'ES', 41.146, 0.683, 15,
   'Montsant lies in Tarragona, Catalonia, and almost surrounds Priorat. It is known above all for full, fruit rich red wines built mainly on Grenache, often blended with Carignan.',
   4, null, null, null, null,
   'https://winefolly.com/deep-dive/spanish-wine-exploration-map/', 'published'),
  ('wr_0189', 'Cava', '{}'::text[], 'ES', 41.401, 1.736, 40,
   'Cava is Spain''s traditional method sparkling wine, made mostly in Catalonia''s Penedès around Sant Sadurní d''Anoia. It is mainly white, from Macabeo, Xarel·lo and Parellada, with some rosé.',
   null, null, null, null, '''Reserva'' needs at least 18 months from tirage to disgorgement, ''Gran Reserva'' at least 30 and ''Paraje Calificado'' at least 36.',
   'https://vinepair.com/articles/wine-101-summer-sparkling-cava/', 'published'),
  ('wr_0190', 'Islas Canarias', '{"DOP Islas Canarias","Canary Islands"}'::text[], 'ES', 28.328, -16.632, 49,
   'Islas Canarias is the umbrella appellation for the whole Canary archipelago, where vines grow on volcanic soils. Listán Blanco and Listán Negro lead, with Malvasía, and most reds are light and fruity.',
   2, null, null, null, 'A wine may carry the name of one island (Tenerife or Fuerteventura) or one municipality when it comes only from there; that name is printed no larger than ''Islas Canarias''.',
   'https://guiapenin.wine/en-islas-canarias-vino-de-calidad-dop', 'published'),
  ('wr_0191', 'Mittelrhein', '{"Middle Rhine"}'::text[], 'DE', 50.220, 7.595, 18,
   'Steep, mostly terraced vineyards on slate along the Rhine between Bingen and Bonn, much of it inside the Rhine Gorge World Heritage area. Riesling covers close to two thirds of the vineyard.',
   null, null, null, null, 'Labels show Qualitätswein or Prädikatswein. From the 2026 vintage a single vineyard (Einzellage) name may appear only on Riesling, Pinot Blanc, Pinot Gris or Pinot Noir.',
   'http://data.europa.eu/eli/C/2026/738/oj', 'published'),
  ('wr_0192', 'Saale-Unstrut', '{}'::text[], 'DE', 50.755, 11.442, 34,
   'Vineyards on the slopes of the Saale and Unstrut valleys, mostly in Saxony-Anhalt with a smaller part in Thuringia, many on stone terraces and shell limestone. One of the northernmost traditional wine regions in Europe, making mostly dry white wine.',
   null, null, null, null, null,
   'http://data.europa.eu/eli/C/2024/5342/oj', 'published'),
  ('wr_0193', 'Sachsen', '{"Saxony"}'::text[], 'DE', 51.179, 13.434, 33,
   'Vineyards on steep slopes of the Elbe valley between Pirna and Diesbar-Seußlitz, around Dresden, Radebeul and Meissen, many on granite and gneiss. Most of the vineyard is planted with white grapes.',
   null, null, null, null, null,
   'http://data.europa.eu/eli/C/2026/5718/oj', 'published'),
  ('wr_0194', 'Hessische Bergstraße', '{"Hessische Bergstrasse"}'::text[], 'DE', 49.871, 8.943, 10,
   'Vineyards on the western slopes of the Odenwald facing the Rhine plain, from Seeheim-Jugenheim south to Heppenheim, with an outlying area around Groß-Umstadt. Spring comes early here, and Riesling is the leading grape.',
   null, null, null, null, null,
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/6412', 'published'),
  ('wr_0195', 'Wien', '{"Vienna"}'::text[], 'AT', 48.211, 16.368, 11,
   'Vineyards inside the city of Vienna, with limestone soils in the west and darker soils in the south. Mostly white wine; Wiener Gemischter Satz, a field blend of several varieties grown and picked together, is the city''s own DAC.',
   null, null, null, null, 'Wiener Gemischter Satz DAC is a dry white from at least three varieties picked and pressed together. Without a smaller origin than Wien it may show no marked oak, and it may not be sold to consumers before 1 December of the harvest year.',
   'https://www.bmluk.gv.at/dam/jcr:957f1ca1-1a73-4005-8350-3171d2b7ea3b/Wien%20Produktspezifikation.pdf', 'published'),
  ('wr_0196', 'Carnuntum', '{}'::text[], 'AT', 48.032, 16.616, 15,
   'Rolling hills east of Vienna between the Danube and the Leitha hills, reaching the Slovak border. A warm Pannonian climate, tempered by the Danube and Lake Neusiedl, suits Zweigelt and Blaufränkisch; Grüner Veltliner, Chardonnay and Pinot Blanc are the white grapes.',
   null, null, null, null, 'Carnuntum DAC is dry. It comes as a regional wine, a village wine (Ortswein) from one of six listed villages, or a single vineyard wine (Riedenwein).',
   'https://www.bmluk.gv.at/dam/jcr:fdf5300e-ebc1-485a-b585-8032f7edd862/Carnuntum%20Produktspezifikation.pdf', 'published'),
  ('wr_0197', 'Thermenregion', '{}'::text[], 'AT', 47.788, 15.961, 32,
   'South of Vienna along the eastern edge of the Vienna Woods, which shelter the vineyards and keep them warm. Its signatures are Zierfandler and Rotgipfler, two local white grapes grown around Gumpoldskirchen and often blended together.',
   null, null, null, null, 'Thermenregion DAC comes as regional, village (Ortswein) and single vineyard (Riedenwein) wine. Regional and village wines are dry with at least 12.0% vol; single vineyard wines need at least 12.5% vol. Village and single vineyard wines may not be rosé.',
   'https://www.bmluk.gv.at/dam/jcr:61dee9ab-713f-40c7-9f7e-16ed7cd15d16/Produktspezifikation_Thermenregion.pdf', 'published'),
  ('wr_0198', 'Traisental', '{}'::text[], 'AT', 48.137, 15.734, 22,
   'A small area along the Traisen river south of the Danube, between Traismauer and St. Pölten. Grüner Veltliner dominates, with Riesling the other DAC grape; warm Pannonian days and cool nights shape the wines.',
   null, null, null, null, 'Traisental DAC is dry Grüner Veltliner or Riesling, with up to 15% of other quality grapes. The Reserve is a fuller style in which slight botrytis and oak are allowed.',
   'https://www.bmluk.gv.at/dam/jcr:4542c2d0-2f92-4fa7-ae67-07189dffffa3/Traisental%20Produktspezifikation.pdf', 'published'),
  ('wr_0199', 'Weststeiermark', '{"West Styria","Schilcherland"}'::text[], 'AT', 46.997, 15.206, 27,
   'Hilly vineyards in western Styria around Deutschlandsberg. Most of the vineyard is Blauer Wildbacher, made into Schilcher, a pale dry rosé with crisp acidity and red berry fruit.',
   null, null, null, null, 'Schilcher is a traditional term for rosé made only from Blauer Wildbacher grown in Styria. The Schilcherland DAC of 2017 was repealed in November 2018 and replaced by Weststeiermark DAC.',
   'https://www.bmluk.gv.at/dam/jcr:cb24a50b-f6c9-4d93-ba60-38ecdccc04ac/Weststeiermark%20Produktspezifikation.pdf', 'published'),
  ('wr_0200', 'Rosalia', '{}'::text[], 'AT', 47.740, 16.413, 8,
   'Vineyards in Burgenland''s Mattersburg district. A red wine area for Blaufränkisch and Zweigelt, with a rosé category, Rosalia DAC Rosé, written into its rules.',
   null, null, null, null, 'Rosalia DAC is red from Blaufränkisch or Zweigelt with at least 12.0% vol; Reserve needs at least 13.0% vol. Rosalia DAC Rosé may use any red quality grape.',
   'https://www.bmluk.gv.at/dam/jcr:62236139-a815-48fe-839f-6f3ad6db4f45/Rosalia%20Produktspezifikation.pdf', 'published'),
  ('wr_0201', 'Mittelburgenland', '{"Blaufränkischland"}'::text[], 'AT', 47.508, 16.503, 15,
   'The Oberpullendorf district of central Burgenland, around Deutschkreutz, Horitschon and Neckenmarkt. Heavy clay and loam soils that hold water suit Blaufränkisch, the only grape of Mittelburgenland DAC.',
   null, null, null, null, 'Mittelburgenland DAC is Blaufränkisch, with up to 15% of other quality grapes. It may carry Classic, a single vineyard name, or Reserve (at least 13.0% vol).',
   'https://www.bmluk.gv.at/dam/jcr:3f3b609e-e45f-455c-b0ed-c5f94b49c931/Mittelburgenland%20Produktspezifikation.pdf', 'published'),
  ('wr_0202', 'Eisenberg', '{}'::text[], 'AT', 47.139, 16.313, 22,
   'Southern Burgenland, in the Oberwart, Güssing and Jennersdorf districts, around the Eisenberg and Deutsch Schützen hills. Slate on the slopes and iron-rich loam below; Blaufränkisch is the main grape, with Welschriesling for village and single vineyard wines.',
   null, null, null, null, 'Eisenberg DAC regional wine is 100% Blaufränkisch. With a village (Ortswein) or single vineyard (Riedenwein) name it may be 100% Blaufränkisch or 100% Welschriesling; no blending.',
   'https://www.bmluk.gv.at/dam/jcr:93568321-4323-437d-ae96-d206eec1339c/Produktspezifikation_Eisenberg.pdf', 'published'),
  ('wr_0203', 'Lisboa', '{"Vinho Regional Lisboa","Estremadura"}'::text[], 'PT', 39.361, -9.189, 42,
   'A long strip of rolling hills running north from Lisbon along the Atlantic, where sea breezes keep the wines fresh. Arinto and Fernão Pires lead the whites; reds draw on Castelão, Aragonez and Touriga Nacional.',
   null, null, null, null, 'Bucelas is white only, from at least 75% Arinto. Carcavelos is a fortified wine aged at least two years in wood and six months in bottle. Vinho Regional Lisboa may be labelled Leve, a light wine of at most 10% alcohol.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/22309', 'published'),
  ('wr_0204', 'Tejo', '{"Ribatejo","DoTejo","Do Tejo","Vinho Regional Tejo"}'::text[], 'PT', 39.248, -8.574, 46,
   'Both banks of the Tagus in central Portugal, formerly called Ribatejo. Riverside plains, clay hills and sandy heath give a wide range of good value wines; Fernão Pires leads the whites, Castelão and Trincadeira the reds.',
   null, null, null, null, 'DoTejo wines may carry the name of one of six recognised sub-regions: Almeirim, Cartaxo, Chamusca, Coruche, Santarém or Tomar.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/3484', 'published'),
  ('wr_0205', 'Açores', '{"Azores"}'::text[], 'PT', 38.514, -28.537, 30,
   'Volcanic islands in the mid Atlantic, where vines grow in small plots walled with lava stone against wind and sea spray. The whites, dry or fortified, are fresh, with marked acidity and a saline edge.',
   null, null, null, null, 'Pico, Biscoitos and Graciosa wines must take at least 85% of their must from Arinto dos Açores, Verdelho and Terrantez do Pico, and their fortified wines must age at least 36 months before bottling.',
   'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=OJ:C_202402366', 'published'),
  ('wr_0206', 'Jurançon', '{"Jurançon Sec"}'::text[], 'FR', 43.263, -0.488, 12,
   'Jurançon, in the Pyrenees foothills southwest of Pau, makes only white wine, from Petit and Gros Manseng. Long known for sweet wines kept fresh by high acidity, it also makes dry Jurançon Sec.',
   null, null, null, null, 'AOC Jurançon is for still white wine only. Dry wines must carry the word sec right after the name and hold at most 4 g/L of sugar; sweet Jurançon holds more than 40 g/L. Vendanges tardives, from the two Mansengs only, needs more than 55 g/L and a vintage on the label.',
   'https://info.agriculture.gouv.fr/boagri/document_administratif-d645c8b2-51ab-4b49-838c-4339610be9ac/telechargement', 'published'),
  ('wr_0207', 'Madiran', '{"AOP Madiran"}'::text[], 'FR', 43.544, -0.127, 10,
   'Madiran, near the Adour in South West France, makes dark, tannic red wines led by Tannat and built to age. The same area makes white Pacherenc du Vic-Bilh, dry or sweet.',
   4, null, 5, null, 'Madiran is for still red wine only, with Tannat at least 60% of each estate''s plantings and of the blend. Pacherenc du Vic-Bilh is white only: dry wines add the word sec (at most 4 g/L of sugar), sweet ones hold at least 45 g/L.',
   'https://info.agriculture.gouv.fr/boagri/document_administratif-394c9c74-735a-4ba0-a779-2e713e1a1801/telechargement', 'published'),
  ('wr_0208', 'Bergerac', '{}'::text[], 'FR', 44.839, 0.479, 21,
   'Bergerac, on the Dordogne east of Bordeaux, uses the Bordeaux grapes, with Merlot leading the reds. It makes reds, rosés and dry whites, and satellite appellations such as Monbazillac add sweet whites.',
   null, null, null, null, 'Bergerac whites must be labelled sec, and rosés above 4 g/L of sugar demi-sec. Côtes de Bergerac whites carry demi-sec, moelleux or doux. Monbazillac may add sélection de grains nobles for wines above 85 g/L of sugar.',
   'https://info.agriculture.gouv.fr/boagri/document_administratif-a078cfed-a9b4-4684-997f-6fc1ea003699/telechargement', 'published'),
  ('wr_0209', 'Gaillac', '{}'::text[], 'FR', 43.933, 1.876, 20,
   'Gaillac, on the Tarn in South West France, works with its own grapes: Mauzac and Len de l''El for whites, Duras, Fer Servadou and Syrah for reds. Wines run from dry to sweet, plus sparkling.',
   null, null, null, null, 'Gaillac covers red, rosé, white and sparkling wine. Dry whites hold at most 4 g/L of sugar; doux whites at least 45 g/L; vendanges tardives at least 100 g/L with a vintage. Méthode ancestrale sparkling comes from Mauzac alone, and primeur reds from Gamay and Duras.',
   'https://info.agriculture.gouv.fr/boagri/document_administratif-b13c44bb-b1f8-4c56-8b41-5fd2d69659cb/telechargement', 'published'),
  ('wr_0210', 'Irouléguy', '{}'::text[], 'FR', 43.159, -1.329, 10,
   'Irouléguy is the only appellation of the French Basque Country, with terraced vines in the Pyrenees foothills around Saint-Étienne-de-Baïgorry. It makes reds from Tannat and Cabernet Franc, plus rosés and whites.',
   null, null, null, null, 'Irouléguy covers still red, rosé and white wine. In red plantings Tannat and Cabernet Franc together make at least 50%, neither above 90%. Whites come only from Courbu, Gros Manseng, Petit Courbu and Petit Manseng.',
   'https://info.agriculture.gouv.fr/boagri/document_administratif-90b99013-a98c-483b-8dd1-07c72e57536b/telechargement', 'published'),
  ('wr_0211', 'Corsica', '{"Corse","Vin de Corse"}'::text[], 'FR', 42.211, 9.400, 43,
   'Corsica''s mountainous vineyards make mostly rosé, with reds from Niellucciu, Sciaccarellu and Grenache and whites from Vermentinu. Patrimonio is led by Niellucciu, Ajaccio by Sciaccarellu.',
   null, null, null, null, 'Vin de Corse, also labelled Corse, may add one of five place names: Calvi, Coteaux du Cap Corse, Figari, Porto-Vecchio or Sartène. Patrimonio reds need at least 90% Nielluccio in the plantings, Ajaccio reds at least 40% Sciaccarello. Muscat du Cap Corse is a fortified sweet Muscat (vin doux naturel).',
   'https://info.agriculture.gouv.fr/boagri/document_administratif-e04c94be-3623-4c86-890a-ab1dbfd4ab59/telechargement', 'published'),
  ('wr_0212', 'Crete', '{"Κρήτη"}'::text[], 'GR', 35.181, 25.118, 23,
   'Greece''s largest island, with most vineyards on the north side, sheltered by a mountain spine and often planted high. Native grapes lead: Vilana and Vidiano for whites; Kotsifali, Mandilaria and Liatiko for reds.',
   null, null, null, null, 'In the dry PDOs, Réserve whites need a year of ageing, six months in oak and three in bottle, and Réserve reds two years, twelve months in oak and six in bottle. Grande Réserve needs two years for whites and four for reds.',
   'https://winesofgreece.org/pgi/pgi-crete/', 'published');

insert into public.grapes
  (grape_code, name, aliases, colour, summary, tastes, aged_note,
   body, acidity, tannin, publication_status)
values
  ('gr_0114', 'Montepulciano', '{}'::text[], 'red',
   'The red grape at the heart of Abruzzo, best known as Montepulciano d''Abruzzo, with flavours of plum, cherry and dried herbs.',
   '{"Plum","Cherry","Blackberry","Dried herbs"}'::text[], 'Bigger, more structured examples gain from time in bottle.', 4, 4, null, 'published'),
  ('gr_0115', 'Verdicchio', '{}'::text[], 'white',
   'The leading white grape of the Marche, at its best in Castelli di Jesi and Matelica, making high acid whites with lemon and almond notes.',
   '{"Lemon","Peach","Almond"}'::text[], 'Its acidity lets the best wines improve in bottle for several years.', null, 4, null, 'published'),
  ('gr_0116', 'Turbiana', '{"Trebbiano di Lugana","Trebbiano di Soave"}'::text[], 'white',
   'The grape of Lugana on Lake Garda, long called Trebbiano di Lugana; DNA studies show it is very close to Verdicchio. It makes high acid whites.',
   '{"Citrus","Orchard fruit","Almond"}'::text[], 'The best wines can age well.', null, 4, null, 'published'),
  ('gr_0117', 'Nero d''Avola', '{"Calabrese"}'::text[], 'red',
   'Sicily''s most important red grape, also known as Calabrese, making dark, full wines with black cherry and plum flavours.',
   '{"Black cherry","Plum","Liquorice","Tobacco"}'::text[], 'Usually drunk young, though the best wines age well.', 4, null, 4, 'published'),
  ('gr_0118', 'Frappato', '{}'::text[], 'red',
   'A light Sicilian red grape centred on Vittoria and blended with Nero d''Avola in Cerasuolo di Vittoria, with strawberry and floral notes.',
   '{"Strawberry","Pomegranate","Violet","White pepper"}'::text[], 'Mostly drunk young, within about three years of the vintage.', 2, 4, 2, 'published'),
  ('gr_0119', 'Grillo', '{}'::text[], 'white',
   'A Sicilian white grape, a crossing of Catarratto and Zibibbo and one of the grapes of Marsala, also made into crisp, light whites.',
   '{"Lemon","Herbs"}'::text[], null, 2, null, null, 'published'),
  ('gr_0120', 'Catarratto', '{"Catarratto Bianco"}'::text[], 'white',
   'A white grape grown almost only in Sicily, long used for Marsala, giving whites with citrus and herbal notes.',
   '{"Citrus","Herbs"}'::text[], null, null, null, null, 'published'),
  ('gr_0121', 'Lambrusco di Sorbara', '{}'::text[], 'red',
   'The lightest and most fragrant Lambrusco grape, from around Modena, making pale, sharply acidic sparkling wines that can resemble rosé.',
   '{"Violet"}'::text[], null, 1, 4, null, 'published'),
  ('gr_0122', 'Lambrusco Grasparossa', '{}'::text[], 'red',
   'A Lambrusco grape from the hills around Castelvetro, south of Modena, making deeply coloured, tannic sparkling reds.',
   '{"Black cherry"}'::text[], null, null, null, 4, 'published'),
  ('gr_0123', 'Sagrantino', '{}'::text[], 'red',
   'An Umbrian red grape centred on Montefalco and counted among the most tannic grapes in Italy, making dark, powerful wines.',
   '{"Plum","Black fruit","Liquorice","Herbs"}'::text[], 'Needs long ageing; the most tannic wines take ten years or more.', 4, 4, 5, 'published'),
  ('gr_0124', 'Fiano', '{}'::text[], 'white',
   'A white grape of Campania, at its best in Fiano di Avellino, with notes of honey, pear and hazelnut and a reputation for ageing well.',
   '{"Honey","Pear","Hazelnut"}'::text[], 'The best wines benefit from a few years in bottle.', null, null, null, 'published'),
  ('gr_0125', 'Greco', '{}'::text[], 'white',
   'The white grape of Greco di Tufo in Campania, making full bodied, fresh whites with peach, pear and almond notes.',
   '{"Peach","Pear","Almond","Tropical fruit"}'::text[], null, 4, 4, null, 'published'),
  ('gr_0126', 'Godello', '{"Gouveio","Agudelo"}'::text[], 'white',
   'A Galician white grape centred on Valdeorras and Monterrei, also planted in Bierzo and Portugal''s Douro, making dry whites of citrus, orchard fruit and saline freshness.',
   '{"Citrus","Apple","White flowers","Saline"}'::text[], 'Takes well to lees ageing, and some versions see subtle oak.', null, 4, null, 'published'),
  ('gr_0127', 'Treixadura', '{"Trajadura","Verdello Rubio"}'::text[], 'white',
   'A white grape of Galicia''s Ribeiro, where it leads most blends, and of Portugal''s Vinho Verde as Trajadura, giving aromatic, floral and fresh dry whites.',
   '{"Floral","Peach","Apricot","Herbal"}'::text[], null, null, null, null, 'published'),
  ('gr_0128', 'Hondarrabi Zuri', '{}'::text[], 'white',
   'The main grape of Txakoli in Spain''s Basque Country, making light, low alcohol, dry whites with high acidity, often with a slight spritz.',
   '{"Citrus","Saline"}'::text[], 'Usually fermented in stainless steel.', 1, 5, null, 'published'),
  ('gr_0129', 'Parellada', '{"Montonec","Martorella","Verda Grossa"}'::text[], 'white',
   'A white grape of Catalonia''s Penedès and one of the three traditional Cava grapes with Macabeo and Xarel·lo, adding fruit and floral aroma to the blend.',
   '{}'::text[], null, null, null, null, 'published'),
  ('gr_0130', 'Listán Negro', '{}'::text[], 'red',
   'The most planted red grape of the Canary Islands, best known from Tenerife''s volcanic soils, making peppery reds, often light and fruity through carbonic maceration.',
   '{"Red cherry","Strawberry","Smoke","Spice"}'::text[], 'Often made by carbonic maceration in a light, fruity style.', null, null, null, 'published'),
  ('gr_0131', 'Blauer Wildbacher', '{"Wildbacher"}'::text[], 'red',
   'A red grape native to Styria in Austria. It is made mostly into Schilcher, a pale dry rosé with crisp acidity and red berry fruit, and also into sparkling wine.',
   '{"Raspberry","Red berries"}'::text[], null, 1, 5, null, 'published'),
  ('gr_0132', 'St. Laurent', '{"Sankt Laurent","Saint Laurent","Svatovavřinecké"}'::text[], 'red',
   'A red grape grown mainly in Austria and the Czech Republic and closely related to Pinot Noir. It gives wines with blackberry fruit and soft tannins.',
   '{"Blackberry"}'::text[], null, null, null, 2, 'published'),
  ('gr_0133', 'Arinto', '{"Pedernã"}'::text[], 'white',
   'A Portuguese white grape grown across most of the country, valued for its firm acidity and often blended in for freshness. It is the main grape of Bucelas.',
   '{"Lemon","Lime","Green apple","Mineral"}'::text[], 'Can age for several years, gaining richer and more complex notes.', 2, 5, null, 'published'),
  ('gr_0134', 'Fernão Pires', '{"Maria Gomes"}'::text[], 'white',
   'One of Portugal''s most planted white grapes, important in Tejo, Lisboa and Bairrada, where it is called Maria Gomes. Aromatic and versatile, made on its own or in blends.',
   '{"Lime","Citrus","Floral"}'::text[], 'Best drunk young.', null, 2, null, 'published'),
  ('gr_0135', 'Castelão', '{"Periquita"}'::text[], 'red',
   'One of the most planted red grapes of southern Portugal, also called Periquita. It likes heat and sandy soils and does best around Palmela on the Setúbal peninsula.',
   '{"Redcurrant","Plum","Game"}'::text[], 'The best examples can age well.', null, 4, 4, 'published'),
  ('gr_0136', 'Petit Manseng', '{}'::text[], 'white',
   'A small, thick skinned white grape of South West France with high acidity. Left to shrivel on the vine it makes sweet Jurançon; it also makes dry whites.',
   '{"Citrus","Apricot","Spice"}'::text[], null, null, 5, null, 'published'),
  ('gr_0137', 'Gros Manseng', '{}'::text[], 'white',
   'A white grape of South West France and the main grape of dry Jurançon Sec. It makes dry whites and also goes into sweet blends.',
   '{"Citrus","Tropical fruit"}'::text[], null, null, null, null, 'published'),
  ('gr_0138', 'Fer Servadou', '{"Braucol","Fer","Pinenc"}'::text[], 'red',
   'A red grape of South West France, called Braucol in Gaillac and Pinenc in Madiran. It gives dark reds with dark berry fruit.',
   '{"Dark berries"}'::text[], null, null, null, null, 'published'),
  ('gr_0139', 'Duras', '{}'::text[], 'red',
   'A red grape of Gaillac, rarely bottled alone and usually blended with Fer Servadou or Syrah. It gives deeply coloured reds with peppery notes.',
   '{"Pepper"}'::text[], null, null, null, null, 'published'),
  ('gr_0140', 'Mauzac', '{}'::text[], 'white',
   'A white grape of Gaillac, also grown in Languedoc, used for still and sparkling wines, dry or sweet. In Gaillac it is the only grape of méthode ancestrale sparkling wine.',
   '{"Apple"}'::text[], null, null, null, null, 'published'),
  ('gr_0141', 'Muscadelle', '{}'::text[], 'white',
   'A white grape of Bordeaux and South West France, used mostly in sweet wines such as Sauternes and Monbazillac and sometimes in dry whites. Musky and floral, with low acidity.',
   '{"Acacia","Honeysuckle"}'::text[], null, null, 2, null, 'published'),
  ('gr_0142', 'Sciaccarellu', '{"Sciaccarello","Sciacarello"}'::text[], 'red',
   'Corsica''s own red grape, the main grape of Ajaccio and Sartène. It makes pale, aromatic reds and rosés with red berry, pepper and herb notes.',
   '{"Red berries","Pepper","Herbs"}'::text[], null, null, null, null, 'published'),
  ('gr_0143', 'Vilana', '{"Βηλάνα"}'::text[], 'white',
   'Crete''s leading white grape, grown mostly in Heraklion and Lasithi. Light, fresh dry whites with lemon, orange and pear notes; the only grape of white Peza.',
   '{"Lemon","Orange","Pear","Jasmine"}'::text[], null, 2, null, null, 'published'),
  ('gr_0144', 'Vidiano', '{"Βιδιανό"}'::text[], 'white',
   'A white grape from Rethymno, now planted across Crete and beyond. Textured, creamy dry whites with stone fruit, citrus and floral notes, often compared with Viognier.',
   '{"Stone fruit","Citrus","Flowers"}'::text[], null, 4, null, null, 'published'),
  ('gr_0145', 'Liatiko', '{"Λιάτικο"}'::text[], 'red',
   'An old red grape of Crete, at home in Dafnes and Sitia. Pale wines with red fruit, sweet spice and soft tannins, made dry or sweet from sun dried grapes.',
   '{"Red fruit","Sweet spice","Dried fruit"}'::text[], 'Can be enjoyed young but improves with cellaring.', 4, null, 2, 'published'),
  ('gr_0146', 'Dafni', '{"Δαφνί"}'::text[], 'white',
   'A rare white grape of Crete, from around Heraklion, revived from near extinction. Aromatic dry whites recalling bay laurel and herbs, with moderate alcohol.',
   '{"Bay laurel","Thyme","Herbs"}'::text[], null, null, 2, null, 'published');

update public.grapes g set similar_grape_id = s.id, similar_note = 'Often compared to Syrah for its full body.' from public.grapes s where s.grape_code = 'gr_0005' and g.grape_code = 'gr_0117';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Suggested as an alternative to Pinot Grigio, with a more savoury character.' from public.grapes s where s.grape_code = 'gr_0024' and g.grape_code = 'gr_0119';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Often likened to white Burgundy for its texture and balance.' from public.grapes s where s.grape_code = 'gr_0002' and g.grape_code = 'gr_0126';
update public.grapes g set similar_grape_id = s.id, similar_note = 'A close relative; St. Laurent wines are often compared with Pinot Noir.' from public.grapes s where s.grape_code = 'gr_0001' and g.grape_code = 'gr_0132';
update public.grapes set aliases = aliases || '{"Cannonau"}'::text[] where grape_code = 'gr_0006';
update public.grapes set aliases = aliases || '{"Chiavennasca"}'::text[] where grape_code = 'gr_0009';
update public.grapes set aliases = aliases || '{"Pinot Bianco"}'::text[] where grape_code = 'gr_0049';
update public.grapes set aliases = aliases || '{"Aragonez","Aragonês"}'::text[] where grape_code = 'gr_0007';
update public.grapes set aliases = aliases || '{"Nielluccio","Niellucciu"}'::text[] where grape_code = 'gr_0010';
update public.grapes set aliases = aliases || '{"Malvoisie de Corse"}'::text[] where grape_code = 'gr_0089';
update public.grapes set aliases = aliases || '{"Bouchy"}'::text[] where grape_code = 'gr_0013';
update public.grapes set aliases = aliases || '{"Muscat of Spina","Moschato Aspro"}'::text[] where grape_code = 'gr_0050';

