  ('wa_0615', 'Thermenregion DAC Wiener Neustadt', '{}'::text[], 'wr_0197', 'mixed', 'Ortswein from villages around Wiener Neustadt.', 5),
  ('wa_0616', 'Thermenregion DAC Bad Vöslau', '{}'::text[], 'wr_0197', 'mixed', 'Ortswein from Kottingbrunn, Berndorf and Bad Vöslau.', 6),
  ('wa_0617', 'Traisental DAC', '{}'::text[], 'wr_0198', 'white', 'Grüner Veltliner or Riesling, dry, without dominant botrytis.', 1),
  ('wa_0618', 'Traisental DAC Reserve', '{}'::text[], 'wr_0198', 'white', 'Fuller style; slight botrytis and oak notes allowed.', 2),
  ('wa_0619', 'Weststeiermark DAC', '{}'::text[], 'wr_0199', 'mixed', 'Regional, village and single vineyard wines; Blauer Wildbacher must be made as Schilcher.', 1),
  ('wa_0620', 'Rosalia DAC', '{}'::text[], 'wr_0200', 'red', 'Blaufränkisch or Zweigelt, or a blend of the two.', 1),
  ('wa_0621', 'Rosalia DAC Reserve', '{}'::text[], 'wr_0200', 'red', 'At least 13.0% vol; a single vineyard name is allowed.', 2),
  ('wa_0622', 'Rosalia DAC Rosé', '{}'::text[], 'wr_0200', 'rose', 'Rosé from one or more red quality grapes.', 3),
  ('wa_0623', 'Mittelburgenland DAC', '{}'::text[], 'wr_0201', 'red', 'Blaufränkisch; may add Classic.', 1),
  ('wa_0624', 'Mittelburgenland DAC Reserve', '{}'::text[], 'wr_0201', 'red', 'Blaufränkisch, at least 13.0% vol, often oak aged.', 2),
  ('wa_0625', 'Eisenberg DAC', '{}'::text[], 'wr_0202', 'mixed', 'Regional wine is pure Blaufränkisch; village and single vineyard wines may also be pure Welschriesling.', 1),
  ('wa_0626', 'Bucelas', '{}'::text[], 'wr_0203', 'white', 'Hillsides of the Trancão valley in Loures, on marl and hard limestone. Still and sparkling whites, at least 75% Arinto.', 1),
  ('wa_0627', 'Alenquer', '{}'::text[], 'wr_0203', 'mixed', 'Slopes and valleys of the Alenquer municipality, sheltered from the Atlantic by hills to the north and west. White and red.', 2),
  ('wa_0628', 'Arruda', '{}'::text[], 'wr_0203', 'mixed', 'Mostly hillside vineyards on clay and limestone, with an Atlantic influence. White and red.', 3),
  ('wa_0629', 'Torres Vedras', '{}'::text[], 'wr_0203', 'mixed', 'Uneven ground with a Mediterranean climate under Atlantic influence, on clay and limestone soils. White and red.', 4),
  ('wa_0630', 'Óbidos', '{}'::text[], 'wr_0203', 'mixed', 'Hills running north west from the Serra de Montejunto to Óbidos, across parts of Bombarral, Cadaval, Caldas da Rainha and Óbidos. White, red, rosé and sparkling.', 5),
  ('wa_0631', 'Encostas d''Aire', '{}'::text[], 'wr_0203', 'mixed', 'The northern end of the region, with the Alcobaça sub-region and the Medieval de Ourém designation for wines made by methods dating from the Middle Ages. Red, white and rosé.', 6),
  ('wa_0632', 'Carcavelos', '{}'::text[], 'wr_0203', 'mixed', 'A very small area near the mouth of the Tagus making only fortified wine, white or red, aged at least two years in wood and six months in bottle.', 7),
  ('wa_0633', 'Almeirim', '{}'::text[], 'wr_0204', 'mixed', 'The municipalities of Almeirim, Alpiarça and Salvaterra de Magos, on riverside alluvium and sandy Charneca soils.', 1),
  ('wa_0634', 'Cartaxo', '{}'::text[], 'wr_0204', 'mixed', 'The municipalities of Azambuja and Cartaxo, from flat river alluvium to rolling clay and limestone hills.', 2),
  ('wa_0635', 'Chamusca', '{}'::text[], 'wr_0204', 'mixed', 'The municipalities of Chamusca, Golegã, Abrantes, Constância, Sardoal and Mação, on alluvium and sandy Charneca soils.', 3),
  ('wa_0636', 'Coruche', '{}'::text[], 'wr_0204', 'mixed', 'The municipalities of Benavente and Coruche, on alluvium and sandy Charneca soils.', 4),
  ('wa_0637', 'Santarém', '{}'::text[], 'wr_0204', 'mixed', 'The municipalities of Rio Maior and Santarém, on alluvium and limestone soils.', 5),
  ('wa_0638', 'Tomar', '{}'::text[], 'wr_0204', 'mixed', 'The municipalities of Tomar, Torres Novas, Alcanena, Entroncamento, Vila Nova da Barquinha and Ferreira do Zêzere, on limestone soils.', 6),
  ('wa_0639', 'Pico', '{}'::text[], 'wr_0205', 'white', 'Vineyards below 100 m in stone walled plots on lava, mainly on the west of the island; the landscape is a UNESCO World Heritage Site since 2004. Dry, sparkling and fortified whites, and wines from overripe grapes.', 1),
  ('wa_0640', 'Biscoitos', '{}'::text[], 'wr_0205', 'white', 'Black basalt vineyards below 100 m in the parish of Biscoitos, on the north of Terceira. Dry, sparkling and fortified whites, and wines from overripe grapes.', 2),
  ('wa_0641', 'Graciosa', '{}'::text[], 'wr_0205', 'white', 'The flattest of the islands, with vines below 150 m in four parishes of Santa Cruz. Dry, sparkling and fortified whites.', 3),
  ('wa_0642', 'Jurançon', '{}'::text[], 'wr_0206', 'white', 'Still white only: sweet, or dry with the mention sec. Late harvest wines add vendanges tardives.', 1),
  ('wa_0643', 'Madiran', '{}'::text[], 'wr_0207', 'red', 'Still red only, led by Tannat.', 1),
  ('wa_0644', 'Pacherenc du Vic-Bilh', '{}'::text[], 'wr_0207', 'white', 'Same area as Madiran. Still white only, sweet or dry with the mention sec.', 2),
  ('wa_0645', 'Bergerac', '{}'::text[], 'wr_0208', 'mixed', 'Still red, rosé and dry white.', 1),
  ('wa_0646', 'Côtes de Bergerac', '{}'::text[], 'wr_0208', 'mixed', 'Still red, and white with more than 4 g/L of sugar.', 2),
  ('wa_0647', 'Monbazillac', '{}'::text[], 'wr_0208', 'white', 'Sweet white, more than 45 g/L of sugar.', 3),
  ('wa_0648', 'Saussignac', '{}'::text[], 'wr_0208', 'white', 'Sweet white, more than 68 g/L of sugar.', 4),
  ('wa_0649', 'Pécharmant', '{}'::text[], 'wr_0208', 'red', 'Still red only.', 5),
  ('wa_0650', 'Rosette', '{}'::text[], 'wr_0208', 'white', 'Medium sweet white, 25 to 51 g/L of sugar.', 6),
  ('wa_0651', 'Montravel', '{}'::text[], 'wr_0208', 'mixed', 'Dry white, and red led by Merlot.', 7),
  ('wa_0652', 'Côtes de Montravel', '{}'::text[], 'wr_0208', 'white', 'Medium sweet white, 25 to 54 g/L of sugar.', 8),
  ('wa_0653', 'Haut-Montravel', '{}'::text[], 'wr_0208', 'white', 'Sweet white, more than 85 g/L of sugar.', 9),
  ('wa_0654', 'Gaillac', '{}'::text[], 'wr_0209', 'mixed', 'Red, rosé, white from dry to sweet, and sparkling, including méthode ancestrale.', 1),
  ('wa_0655', 'Gaillac premières côtes', '{}'::text[], 'wr_0209', 'white', 'White only, from 11 communes on the right bank of the Tarn.', 2),
  ('wa_0656', 'Irouléguy', '{}'::text[], 'wr_0210', 'mixed', 'Still red, rosé and white.', 1),
  ('wa_0657', 'Vin de Corse', '{}'::text[], 'wr_0211', 'mixed', 'Also labelled Corse. Still red, rosé and white across the island.', 1),
  ('wa_0658', 'Vin de Corse Calvi', '{}'::text[], 'wr_0211', 'mixed', 'Geographic name added to Vin de Corse or Corse.', 2),
  ('wa_0659', 'Vin de Corse Coteaux du Cap Corse', '{}'::text[], 'wr_0211', 'mixed', 'Geographic name added to Vin de Corse or Corse.', 3),
  ('wa_0660', 'Vin de Corse Figari', '{}'::text[], 'wr_0211', 'mixed', 'Geographic name added to Vin de Corse or Corse.', 4),
  ('wa_0661', 'Vin de Corse Porto-Vecchio', '{}'::text[], 'wr_0211', 'mixed', 'Geographic name added to Vin de Corse or Corse.', 5),
  ('wa_0662', 'Vin de Corse Sartène', '{}'::text[], 'wr_0211', 'mixed', 'Geographic name added to Vin de Corse or Corse.', 6),
  ('wa_0663', 'Patrimonio', '{}'::text[], 'wr_0211', 'mixed', 'Reds and rosés led by Nielluccio; whites from Vermentino only.', 7),
  ('wa_0664', 'Ajaccio', '{}'::text[], 'wr_0211', 'mixed', 'Reds and rosés led by Sciaccarello; whites mainly Vermentino.', 8),
  ('wa_0665', 'Muscat du Cap Corse', '{}'::text[], 'wr_0211', 'white', 'Fortified sweet white (vin doux naturel) from Muscat à petits grains.', 9),
  ('wa_0666', 'Peza', '{}'::text[], 'wr_0212', 'mixed', 'PDO for dry white from Vilana alone and dry red from Kotsifali with Mandilaria.', 1),
  ('wa_0667', 'Archanes', '{}'::text[], 'wr_0212', 'red', 'PDO for dry red from Kotsifali and Mandilaria.', 2),
  ('wa_0668', 'Dafnes', '{}'::text[], 'wr_0212', 'red', 'PDO for Liatiko: dry red, sweet fortified red and sweet red from sun dried grapes.', 3),
  ('wa_0669', 'Sitia', '{}'::text[], 'wr_0212', 'mixed', 'PDO for dry white from Vilana and Thrapsathiri, dry red from Liatiko with Mandilaria, and sweet Liatiko, fortified or from sun dried grapes.', 4),
  ('wa_0670', 'Handakas - Candia', '{}'::text[], 'wr_0212', 'mixed', 'PDO for dry white from Vilana with Vidiano, Assyrtiko, Athiri and Thrapsathiri, and dry red from Kotsifali and Mandilaria.', 5),
  ('wa_0671', 'Malvasia Handakas - Candia', '{}'::text[], 'wr_0212', 'white', 'Sweet white from sun dried grapes, natural or fortified, from Assyrtiko, Athiri, Vidiano, Thrapsathiri and Liatiko, with at most 15% Muscat and Malvasia di Candia Aromatica. At least two years of oxidative ageing.', 6),
  ('wa_0672', 'Malvasia Sitia', '{}'::text[], 'wr_0212', 'white', 'Sweet white from sun dried grapes, natural or fortified, from Assyrtiko, Athiri, Thrapsathiri and Liatiko, with at most 15% Muscat and Malvasia di Candia Aromatica. At least two years of oxidative ageing.', 7)
) as v(code, name, aliases, region, colour, note, ord)
